const {config} = $json;
return [{json:{
  projeto:'RUPTURA ONE',
  config,
  brief:{
    tema:config.tema,
    publico:config.publico,
    idioma:config.idioma,
    plataformas:config.plataformas,
    objetivo:'Gerar um vídeo curto útil, original, verificável e adequado às plataformas, sem promessas enganosas.',
    duracao_min:config.duracao_min,
    duracao_max:config.duracao_max,
    tom:'direto, natural, didático e envolvente'
  }
}}];

const {config, brief} = $json;
const schema = {
  type:'object',
  properties:{
    titulo:{type:'string'},
    gancho:{type:'string'},
    roteiro:{type:'string'},
    legenda:{type:'string'},
    cta:{type:'string'},
    hashtags:{type:'array',items:{type:'string'}},
    ideia_visual:{type:'string'},
    texto_tela:{type:'string'},
    duracao_segundos:{type:'integer'},
    cenas:{type:'array',items:{type:'object',properties:{
      cena:{type:'integer'},
      duracao_segundos:{type:'integer'},
      visual:{type:'string'},
      narracao:{type:'string'},
      texto_tela:{type:'string'}
    },required:['cena','duracao_segundos','visual','narracao','texto_tela']}}
  },
  required:['titulo','gancho','roteiro','legenda','cta','hashtags','ideia_visual','texto_tela','duracao_segundos','cenas']
};
const prompt = [
'Você é o cérebro editorial do RUPTURA ONE.',
'Crie conteúdo original e útil. Não invente estatísticas, estudos, fontes, preços, depoimentos ou resultados.',
'Não prometa dinheiro garantido. Não faça alegações médicas, financeiras ou jurídicas sem base.',
'Escreva em português do Brasil, em linguagem falada.',
'Crie UM pacote para vídeo vertical curto.',
'Retorne SOMENTE JSON conforme o schema.',
'BRIEF:',
JSON.stringify(brief)
].join('\n');
const geminiBody = {
  systemInstruction:{parts:[{text:'Você é um editor-chefe rigoroso para vídeos curtos. Priorize clareza, retenção, utilidade e conformidade.'}]},
  contents:[{role:'user',parts:[{text:prompt}]}],
  generationConfig:{
    thinkingConfig:{thinkingLevel:'low'},
    responseMimeType:'application/json',
    responseSchema:schema,
    maxOutputTokens:3000
  }
};
return [{json:{projeto:'RUPTURA ONE',config,brief,geminiBody}}];

const r=$input.first().json;
if(r.error) throw new Error('Gemini API: '+(r.error.message||JSON.stringify(r.error)));
const c=r.candidates?.[0];
if(!c) throw new Error('Gemini não retornou candidates.');
const reason=c.finishReason;
if(reason && reason!=='STOP') throw new Error('Gemini terminou com finishReason='+reason);
const text=(c.content?.parts||[]).map(p=>p.text||'').join('').trim();
if(!text) throw new Error('Gemini não retornou conteúdo.');
let clean=text.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
const a=clean.indexOf('{'), b=clean.lastIndexOf('}');
if(a<0||b<=a) throw new Error('Gemini não retornou JSON válido.');
let data;
try{data=JSON.parse(clean.slice(a,b+1));}catch(e){throw new Error('JSON inválido do Gemini: '+clean.slice(0,1000));}
return [{json:data}];

const d=$input.first().json;
const required=['titulo','gancho','roteiro','legenda','cta','hashtags','ideia_visual','texto_tela','duracao_segundos','cenas'];
const missing=required.filter(k=>d[k]===undefined||d[k]===null);
if(missing.length) throw new Error('QA REPROVADO — faltando: '+missing.join(', '));
if(!Array.isArray(d.hashtags)||d.hashtags.length<4||d.hashtags.length>6) throw new Error('QA REPROVADO — hashtags deve ter 4 a 6 itens.');
if(!Array.isArray(d.cenas)||d.cenas.length<3||d.cenas.length>8) throw new Error('QA REPROVADO — cenas deve ter 3 a 8 itens.');
if(!Number.isInteger(d.duracao_segundos)||d.duracao_segundos<30||d.duracao_segundos>60) throw new Error('QA REPROVADO — duração deve ser 30–60s.');
if(d.gancho.length<15) throw new Error('QA REPROVADO — gancho muito curto.');
if(d.roteiro.length<200) throw new Error('QA REPROVADO — roteiro muito curto.');
const soma=d.cenas.reduce((s,c)=>s+(Number(c.duracao_segundos)||0),0);
if(soma<25||soma>70) throw new Error('QA REPROVADO — soma das cenas incoerente: '+soma+'s.');
return [{json:{...d,qa:{aprovado:true,duracao_cenas:soma,verificacoes:['campos','estrutura','hashtags','duracao','gancho','roteiro','cenas']}}}];

const d=$input.first().json;
let t=0;
const clips=d.cenas.map((c)=>{
  const length=Math.max(1,Number(c.duracao_segundos)||5);
  const text=String(c.texto_tela||c.narracao||'').slice(0,240);
  const clip={asset:{type:'rich-text',text,font:{family:'Montserrat SemiBold',size:64},align:{horizontal:'center',vertical:'middle'},color:'#ffffff'},start:t,length};
  t+=length;
  return clip;
});
const edit={
  timeline:{background:'#111111',tracks:[{clips}]},
  output:{format:'mp4',resolution:'hd',aspectRatio:'9:16',fps:30}
};
return [{json:{...d,shotstack_edit:edit,producao:{formato:'9:16',resolucao:'HD vertical',duracao_segundos:t,renderizador:'Shotstack',observacao:'Render de teste com texto; para produção editorial final, usar apenas mídia licenciada ou própria.'}}}];

const r=$input.first().json;
if(r.error) throw new Error('Shotstack API: '+(r.error.message||JSON.stringify(r.error)));
const id=r.response?.id;
if(!id) throw new Error('Shotstack não retornou response.id.');
const base=$('08 — MONTAR VÍDEO').first().json;
return [{json:{render_id:id,tentativas:0,config:base.config,conteudo:base}}];

const previous=$('11 — SALVAR RENDER ID').first().json;
const attempt=(previous.tentativas||0)+1;
if(attempt>30) throw new Error('Timeout lógico: render não concluiu após 30 verificações.');
return [{json:{...previous,tentativas:attempt}}];

const base=$('11 — SALVAR RENDER ID').first().json.conteudo;
const r=$input.first().json;
const url=r.response?.url||null;
if(!url) throw new Error('Shotstack marcou done, mas não retornou response.url.');
return [{json:{...base,video_url:url,render_id:r.response.id,render_status:'done',resultado:'VIDEO_MP4_RENDERIZADO',publicacao:{status:'AGUARDANDO_PUBLICACAO',video_url:url}}}];

const d=$input.first().json; const c=d.config;
if(!d.video_url) throw new Error('TikTok: vídeo não existe.');
return [{json:{plataforma:'TikTok',projeto:d.projeto||'RUPTURA ONE',video_url:d.video_url,request:{method:'POST',url:'https://open.tiktokapis.com/v2/post/publish/video/init/',headers:{Authorization:'Bearer '+c.tiktok_access_token,'Content-Type':'application/json; charset=UTF-8'},body:{post_info:{title:[d.legenda,...d.hashtags].join(' ').slice(0,2200),privacy_level:'SELF_ONLY',disable_duet:false,disable_comment:false,disable_stitch:false,is_aigc:true},source_info:{source:'PULL_FROM_URL',video_url:d.video_url}}},observacao:'Para PULL_FROM_URL, o domínio/prefixo da URL do vídeo precisa estar verificado no TikTok. Cliente não auditado publica apenas em modo privado.'}}];

const d=$input.first().json; const c=d.config;
if(!d.video_url) throw new Error('Instagram: vídeo não existe.');
return [{json:{plataforma:'Instagram Reels',video_url:d.video_url,request:{create_container:{method:'POST',url:'https://graph.facebook.com/v24.0/'+c.instagram_user_id+'/media',body:{media_type:'REELS',video_url:d.video_url,caption:[d.legenda,...d.hashtags].join(' '),share_to_feed:true}},publish_after_ready:{method:'POST',url:'https://graph.facebook.com/v24.0/'+c.instagram_user_id+'/media_publish',body:{creation_id:'USAR_ID_DO_CONTAINER'}}},observacao:'O container deve ser criado, ter status pronto e só então ser publicado. Requer credenciais/permissões Meta adequadas.'}}];

const d=$input.first().json;
if(!d.video_url) throw new Error('YouTube: vídeo não existe.');
return [{json:{plataforma:'YouTube Shorts',video_url:d.video_url,youtube:{metadata:{title:d.titulo,description:[d.legenda,d.cta,...d.hashtags].join('\n'),privacyStatus:'private'},auth:'OAuth 2.0 com escopo youtube.upload',upload:'Usar videos.insert multipart/resumable ou nó YouTube do n8n com credencial OAuth2.'},observacao:'Projetos OAuth não devem armazenar senha/token fixo no workflow.'}}];
